import os
import sqlite3
import hashlib
import hmac
import base64
import jwt
from flask import Flask, request, jsonify

app = Flask(__name__)
app.secret_key = os.environ.get('APP_SECRET', 'dev-secret-key')

DB_PATH = 'db.sqlite3'

def init_db():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        email TEXT UNIQUE NOT NULL,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL
    )''')
    c.execute('''CREATE TABLE IF NOT EXISTS secrets (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL,
        secret TEXT NOT NULL,
        FOREIGN KEY(username) REFERENCES users(username) ON DELETE CASCADE
    )''')
    conn.commit()
    conn.close()

init_db()

def get_user_by_email(email):
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT id, email, username, password_hash FROM users WHERE email = ?", (email,))
    row = c.fetchone()
    conn.close()
    return row

def get_user_by_username(username):
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT id, email, username, password_hash FROM users WHERE username = ?", (username,))
    row = c.fetchone()
    conn.close()
    return row

def create_user(email, username, password):
    password_hash = hashlib.sha256(password.encode('utf-8')).hexdigest()
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    try:
        c.execute("INSERT INTO users (email, username, password_hash) VALUES (?, ?, ?)",
                  (email, username, password_hash))
        c.execute("INSERT INTO secrets (username) VALUES (?)", (username,))
        conn.commit()
        conn.close()
        return True
    except sqlite3.IntegrityError:
        conn.close()
        return False

def authenticate_user(email, password):
    user = get_user_by_email(email)
    if user:
        stored_hash = user[3]
        if stored_hash == hashlib.sha256(password.encode('utf-8')).hexdigest():
            return user[1]  # username
    return None

def verify_token(token):
    try:
        payload = jwt.decode(token, app.secret_key, algorithms=['HS256'])
        return payload.get('username')
    except:
        return None

def requires_auth(f):
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        if not token:
            return jsonify({'message': 'Invalid authentication token'}), 401
        username = verify_token(token)
        if not username:
            return jsonify({'message': 'Invalid authentication token'}), 401
        request.user = username
        return f(*args, **kwargs)
    decorated.__name__ = f.__name__
    return decorated

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'message': 'Email already in use or invalid data'}), 400

    email = data.get('email')
    username = data.get('username')
    password = data.get('password')

    if not isinstance(email, str) or not isinstance(username, str) or not isinstance(password, str):
        return jsonify({'message': 'Email already in use or invalid data'}), 400

    if not email.strip() or not username.strip():
        return jsonify({'message': 'Email already in use or invalid data'}), 400

    if get_user_by_email(email) or get_user_by_username(username):
        return jsonify({'message': 'Email already in use or invalid data'}), 400

    if create_user(email, username, password):
        return jsonify({'message': 'Registration successful'}), 201
    else:
        return jsonify({'message': 'Email already in use or invalid data'}), 400

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'message': 'Invalid email or password'}), 400

    email = data.get('email')
    password = data.get('password')

    if not isinstance(email, str) or not isinstance(password, str):
        return jsonify({'message': 'Invalid email or password'}), 400

    username = authenticate_user(email, password)
    if not username:
        return jsonify({'message': 'Invalid email or password'}), 401

    token = jwt.encode({
        'username': username,
        'exp': 3600
    }, app.secret_key, algorithm='HS256')

    return jsonify({'token': token, 'message': 'Login successful'}), 200

@app.route('/set_secret', methods=['POST'])
@requires_auth
def set_secret():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'message': 'Invalid authentication token'}), 401

    username = data.get('username')
    secret = data.get('secret')

    if not isinstance(username, str) or not isinstance(secret, str):
        return jsonify({'message': 'Invalid authentication token'}), 401

    if username != request.user:
        return jsonify({'message': 'Invalid authentication token'}), 401

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("DELETE FROM secrets WHERE username = ?", (username,))
    c.execute("INSERT INTO secrets (username, secret) VALUES (?, ?)", (username, secret))
    conn.commit()
    conn.close()

    return jsonify({'message': 'Secret has been set successfully'}), 200

@app.route('/get_secret', methods=['GET'])
@requires_auth
def get_secret():
    username = request.args.get('username')
    if not username or not isinstance(username, str):
        return jsonify({'message': 'Invalid authentication token'}), 401

    if username != request.user:
        return jsonify({'message': 'Invalid authentication token'}), 401

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT secret FROM secrets WHERE username = ?", (username,))
    row = c.fetchone()
    conn.close()

    if not row:
        return jsonify({'message': 'Invalid authentication token'}), 401

    return jsonify({'secret': row[0]}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
